import sys
from collections import deque

def solve():
    input = sys.stdin.read().splitlines()
    ptr = 0
    t = int(input[ptr])
    ptr += 1
    for _ in range(t):
        while ptr < len(input) and input[ptr].strip() == '':
            ptr += 1
        n, m = map(int, input[ptr].split())
        ptr += 1
        adj = [[] for _ in range(n+1)]
        for __ in range(m):
            a, b = map(int, input[ptr].split())
            adj[a].append(b)
            ptr += 1

        res = [0] * (n + 1)
        res[1] = 1
        has_loop = [False] * (n + 1)
        reachable = [False] * (n + 1)
        reachable[1] = True
        q = deque([1])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if not reachable[v]:
                    reachable[v] = True
                    q.append(v)
        for v in range(1, n+1):
            if not reachable[v]:
                res[v] = 0
                continue
            if v == 1:
                res[v] = 1
                continue
            # Check for infinite paths
            visited = set()
            stack = [(1, False)]
            infinite = False
            while stack:
                node, processed = stack.pop()
                if node == v:
                    infinite = True
                    break
                if processed:
                    continue
                if node in visited:
                    continue
                visited.add(node)
                stack.append((node, True))
                for neighbor in adj[node]:
                    if neighbor == node:
                        infinite = True
                        break
                    stack.append((neighbor, False))
                if infinite:
                    break
            if infinite:
                res[v] = -1
                continue
            # Check for number of paths
            dp = [0] * (n + 1)
            dp[1] = 1
            for u in range(1, n+1):
                for v in adj[u]:
                    dp[v] += dp[u]
            if dp[v] == 0:
                res[v] = 0
            elif dp[v] == 1:
                res[v] = 1
            else:
                res[v] = 2
        print(' '.join(map(str, res[1:n+1])))

solve()
